import { build } from "esbuild";
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";

// Next/Turbopack can copy a new URL(worker.ts) asset without compiling its
// imports. Ship the small, self-contained ESM worker as an inspectable asset.
const output = new URL("../src/dom/map-encoder.worker.js", import.meta.url);
const result = await build({
  entryPoints: [fileURLToPath(new URL("../src/dom/map-encoder.worker.ts", import.meta.url))],
  absWorkingDir: fileURLToPath(new URL("..", import.meta.url)),
  bundle: true, format: "esm", platform: "browser", target: "es2022", write: false,
  legalComments: "inline",
  banner: { js: "// Generated by scripts/bundle-material-worker.mjs. MIT: see ../../LICENSE.\n// Source: Guangcai a24ffb03 Glass-HQ PNG worker; Next static-module adaptation." },
});
const generated = Buffer.from(result.outputFiles[0].contents);
if (process.argv.includes("--check")) {
  const current = await readFile(output).catch(error => {
    if (error.code === "ENOENT") return null;
    throw error;
  });
  if (!current || !current.equals(generated)) {
    console.error("Glass material worker is missing or stale. Regenerate with: node site/vendor/glass-hq/scripts/bundle-material-worker.mjs");
    process.exitCode = 1;
  }
} else {
  await writeFile(output, generated);
}
